/* readaloud-data.js — тексты для зачитывания Мастером по сессиям, в порядке игры.
   Источник: сценарии session1–3.html (блоки «читать вслух» и реплики NPC) + дописанные ключевые моменты.
   Поля: session, scene, id, title, when (когда читать), trigger (тег момента), text, notes?, map?, cutscene?, variants? [{if,text}]. */
window.READALOUD=[{"session": 1,"scene": "Начало сессии","id": "s1-start","title": "Дорога в Солтхейвен","when": "Самое начало игры, сразу после пролога (или вместо него) — герои едут на почтовой повозке","trigger": "начало сессии","text": "Почтовая повозка трясётся по каменистой дороге последние два часа. Слева тянутся чёрные скалы, справа — ничего, только серая стена тумана, из которой иногда доносится шум прибоя. Возница, немолодой мужчина в промасленном плаще, за всю дорогу сказал вам ровно две фразы. Третью он говорит сейчас, не оборачиваясь: «Солтхейвен. Дальше не поеду». Он останавливается у первого дома, кидает ваши вещи на дорогу и разворачивает лошадей так быстро, будто за ним гонятся.","notes": "Перед текстом можно показать пролог. Положите на стол Шкалу Мглы на 1. После текста спросите каждого игрока, зачем его герой едет в Солтхейвен.","map": "01-region","cutscene": "intro"},
{"session": 1,"scene": "Сцена 1. Лунатики","id": "s1-bell","title": "Колокол и лунатики","when": "Повозка спустилась к причалу, наступила ночь — перед испытанием навыков","trigger": "вход в локацию","text": "Повозка спускается к морю уже в темноте. Туман такой густой, что фонари на причале кажутся луной под водой. И тогда, откуда-то с моря, звучит колокол — один удар, низкий, будто из-под земли. Вы чувствуете его не ушами, а зубами. В тишине после него вы слышите шаги. Трое горожан в ночных рубахах идут к воде босиком. Глаза открыты, лица спокойные, почти счастливые. Первый уже заходит в море по колено.","notes": "Дальше — испытание навыков: 3 успеха до 3 провалов (Атлетика СЛ 12/13, Убеждение или Медицина СЛ 12, Внимательность СЛ 11 — все смотрят на юг, на маяк). Каждый провал — один горожанин уходит под воду.","map": "01-region"},
{"session": 1,"scene": "Сцена 1. Лунатики","id": "s1-tobias","title": "Тобиас приходит в себя","when": "Испытание навыков закончено, последний лунатик очнулся у героев в руках","trigger": "после боя","text": "Последний лунатик вздрагивает у вас в руках и открывает глаза. Это худой рыбак лет сорока с седой щетиной. Он смотрит на воду, потом на вас, и его начинает трясти. «Она пела, — шепчет он. — Под водой. Так красиво пела».\n\n— Марта Грей: «Тоби! Боги, Тоби… Я же три дня тебя хоронила!» (Поворачивается к героям.) «Кто вы? Неважно. Вы его вытащили. Идёмте в дом, у меня суп и сухие одеяла. И… вот. Муж берёг на чёрный день. Похоже, он настал».","notes": "Награда: по зелью лечения каждому, ночлег у Марты бесплатно. Шкала Мглы −1, если спасли всех троих. Имя Тобиаса назовите, когда Марта подбежит с фонарём."},
{"session": 1,"scene": "Сцена 2. Город, который не спит","id": "s1-morning","title": "Утро в тумане","when": "Начало расследования: утро после ночи у Марты, герои выходят в город","trigger": "вход в локацию","text": "Утро в Солтхейвене не наступает — оно просто становится чуть светлее. Туман лежит на крышах, на мостках, на лодках, вытащенных на берег. Лодок много: никто не выходит в море. Рыбаки сидят на перевёрнутых корзинах и чинят сети, которые не нужно чинить. Когда вы проходите мимо, разговоры стихают.","notes": "Свободное расследование. Любые три зацепки ведут к Гроту Бочек. Если игроки застряли — подсказку даёт Тобиас или Марта ведёт к Ингрид.","map": "02-solthaven"},
{"session": 1,"scene": "Сцена 2. Город, который не спит","id": "s1-pier","title": "Причал и старый Хенн","when": "Герои приходят на причал или рыбный рынок (место 1 на карте города)","trigger": "встреча NPC","text": "На причале пахнет солью и тухлой рыбой. Торговка продаёт вчерашнюю селёдку за полцены, и никто не берёт. Старый рыбак с трубкой сидит на краю мостков и смотрит в туман так, будто ждёт оттуда кого-то.\n\n— Старый рыбак Хенн: «Вы про колокол? Я его сорок лет назад слышал, мальчишкой. Ночью, когда Ис-Мерин тонул. Тогда он звонил трижды. Сейчас — один раз за ночь. Пока один. И вот что я скажу: контрабандисты Дожа с прошлой луны перестали возить бренди. Сидят в своём гроте на севере, как крабы. Дож не из пугливых. Значит, что-то его напугало».","map": "02-solthaven"},
{"session": 1,"scene": "Сцена 2. Город, который не спит","id": "s1-baklan","title": "Таверна «Пьяный Баклан»","when": "Герои входят в таверну (место 2)","trigger": "вход в локацию","text": "Низкий зал, закопчённые балки, над стойкой — чучело баклана с бутылкой в клюве. Хозяйка, крупная рыжая женщина, протирает кружку, которая и так чистая. В углу трое завсегдатаев играют в кости, никто не выигрывает и никто не уходит домой: дома — у воды.\n\n— Ингрид, хозяйка: «Эль — четыре медяка. Слухи — золотой, или угостите тех троих. Про Ис-Мерин хотите? У них там было три колокола: бронзовый, серебряный и Великий. Жрицы звонили в них, чтобы море было тихим. А потом позвонили не так, и море взяло весь город. Сказки, скажете? Сказки не звонят по ночам».","notes": "Здесь же сидит капитан Орвин Хейл. Если герой пришёл с причиной «Долг капитану» и назовёт его по имени: «Потом. Сначала разберитесь, что творится, а потом поговорим про море».","map": "10-baklan"},
{"session": 1,"scene": "Сцена 2. Город, который не спит","id": "s1-marta","title": "Дом Марты: рассказ Тобиаса","when": "Герои расспрашивают Тобиаса у него дома (место 3) — днём, когда он немного отогрелся","trigger": "встреча NPC","text": "В доме Марты пахнет супом и мокрой шерстью. Тобиас сидит у очага, закутанный в два одеяла, и всё равно дрожит. Он долго смотрит в огонь, прежде чем заговорить.\n\n— Тобиас Грей: «Я плохо помню. Вода была тёплая, как молоко. Там была женщина в белом. Она пела без слов, а я понимал. Она сказала: \"Бронзовый уже у меня в руках. Скоро зазвонит серебряный. И тогда все вы вернётесь домой\"». (Показывает ладони: на них ожоги в форме колокольного языка.)","notes": "Покажите игрокам ладони Тобиаса: ожоги в форме колокольного языка.","map": "11-dom-marty"},
{"session": 1,"scene": "Сцена 2. Город, который не спит","id": "s1-chapel","title": "Часовня Морской Матери","when": "Герои поднимаются к часовне на холме (место 4)","trigger": "вход в локацию","text": "Маленькая каменная часовня на холме. На стенах — сотни деревянных рыбок с именами: так здесь молятся за тех, кто в море. Свежие рыбки висят отдельно, на верёвке у алтаря. Их одиннадцать.\n\n— Сестра Аделина: «Одиннадцать за месяц. Все жили у воды. Я пишу их имена и вешаю, хотя Мать знает, это не помогает. Помогает вот что». (Показывает плошку с восковыми шариками.) «Затычки для ушей. Медяк за пару. Смейтесь, но с тех пор, как я в них сплю, я ни разу не проснулась в воде».","notes": "Аделина продаёт восковые затычки: медяк за пару. Они дают преимущество на спасброски от песни колокола — напомните об этом позже.","map": "12-chasovnya"},
{"session": 1,"scene": "Сцена 2. Город, который не спит","id": "s1-kob","title": "Староста Коб","when": "Герои приходят в дом старосты у площади (место 5)","trigger": "встреча NPC","text": "Дом старосты — единственный в городе с крашеной оградой. Коб открывает сам, в халате, и сразу втягивает вас внутрь, оглядываясь на улицу. Говорит он шёпотом, хотя вокруг никого.\n\n— Староста Коб: «Тише, тише, ради всех богов. Если вы начнёте кричать о проклятиях, половина города сбежит, а вторая половина сожжёт часовню. Мне нужно, чтобы всё прекратилось. Тихо. Пятьдесят золотых, если прекратится. И ещё пятьдесят, если пропавшие вернутся. Живыми, разумеется. Ну… или хоть какими».","notes": "Награда старосты: 50 зм, если всё прекратится, и ещё 50 зм, если пропавшие вернутся.","map": "14-dom-staresty"},
{"session": 1,"scene": "Сцена 2. Город, который не спит","id": "s1-pip","title": "Лавка «Крюк и узел»","when": "Герои заходят в лавку (место 6) — за покупками или с вопросами","trigger": "встреча NPC","text": "Колокольчик над дверью не звенит — его язык обмотан тряпкой. В лавке тесно от верёвок, сетей, фонарей и ящиков с гвоздями. За прилавком — лысоватый мужчина с карандашом за ухом. Он улыбается вам так широко, будто уже подсчитал, сколько вы потратите.\n\n— Пип Варнак: «Ищете что-то? У меня всё есть, кроме скидок. А, вы спрашиваете… Хм. Информация — тоже товар. Ладно, бесплатно, вы мне нравитесь. Месяц назад кто-то купил у меня триста футов цепи и лебёдку. Сказали: для часовни, повесить колокол. Только часовне колокол не нужен, у неё свой есть. Покупатель? Мейв. Дочка смотрителя маяка».","notes": "Цены лавки — в журнале Мастера. Покупательница цепи и лебёдки — Мейв, дочь смотрителя маяка.","map": "13-kryuk-i-uzel"},
{"session": 1,"scene": "Сцена 2. Город, который не спит","id": "s1-tracks","title": "Борозды за складами","when": "Герои осматривают склады на северном краю города (место 7)","trigger": "находка","text": "За складами — тропа вдоль скал на север. На влажной земле видны глубокие борозды: что-то очень тяжёлое волокли по земле. Но волокли не к гроту, а наоборот — от него, на юг, в сторону маяка. Следы свежие, им не больше недели.","map": "02-solthaven"},
{"session": 1,"scene": "Сцена 3. Грот Бочек","id": "s1-grot","title": "Вход в грот","when": "Герои дошли по тропе до полосы гальки у входа в грот — до проверки Скрытности","trigger": "вход в локацию","text": "Тропа обрывается у узкой полосы гальки. В скале перед вами — чёрная щель, достаточно широкая, чтобы прошли двое. Вода затекает внутрь при каждой волне и с шипением уходит обратно. Изнутри пахнет дымом, ромом и мокрой шерстью. И слышно, как кто-то кашляет — тяжело, со свистом.","notes": "Если идут скрытно: групповая Ловкость (Скрытность) против пассивной Внимательности бандитов 10 — застают склад врасплох.","map": "03-grot-bochek"},
{"session": 1,"scene": "Сцена 3. Грот Бочек","id": "s1-dozh","title": "Арбалеты из-за ящиков","when": "Герои входят в пещеру-склад (зона 2) — перед броском инициативы или переговорами","trigger": "начало боя","text": "Пещера за проходом заставлена ящиками и бочками в два человеческих роста. Между ними горит одинокий фонарь. Над вами щёлкают взводимые арбалеты, и хриплый голос из глубины пещеры говорит: «Ещё шаг — и будете похожи на подушечку для иголок. Кто такие?»","notes": "Дож не хочет боя: Харизма (Убеждение) СЛ 13 (преимущество, если упомянуть певчих или колокол). 3 бандита за ящиками (укрытие +2 КД), Дож вступает на 2-м раунде.","map": "03-grot-bochek"},
{"session": 1,"scene": "Сцена 3. Грот Бочек","id": "s1-dozh-talk","title": "Рассказ «Сиплого» Дожа","when": "Дож сдался или договорился с героями","trigger": "встреча NPC","text": "— «Сиплый» Дож: «Мы нашли его, когда искали старый тайник. Бронзовый колокол. Прямо там, в глубине, висел на гнилой раме, будто ждал нас. Я хотел продать его в столице. А через три дня пришли они. Певчие. Пели, пока мои ребята не начали ходить в воду, как лунатики. Двоих не вытащили. Колокол утащили через лаз в море. Хотите их найти? Я пойду с вами. Хотя нет. Не пойду. Но скажу, где искать».","map": "03-grot-bochek"},
{"session": 1,"scene": "Сцена 3. Грот Бочек","id": "s1-flooded","title": "Затопленный проход","when": "Герои спускаются из склада в зону 4","trigger": "вход в локацию","text": "Пещера уходит вниз, и вода поднимается вам до пояса, потом до груди. Она ледяная. Свод здесь низкий, с него капает, и где-то над головой с тихим хрустом сыплется песок.","notes": "Ловушка: Внимательность СЛ 13 — заметить трещины. Громкий бой или крик здесь — обвал: спасбросок Ловкости СЛ 12, иначе 2d6 дробящего. Вода — трудная местность.","map": "03-grot-bochek"},
{"session": 1,"scene": "Сцена 3. Грот Бочек","id": "s1-crabs","title": "Логово крабов","when": "Герои выходят в круглый грот (зона 5) — до того, как крабы атакуют","trigger": "начало боя","text": "Проход выводит в круглый грот с лужами, оставленными приливом. На дне луж белеют кости — рыбьи и, кажется, не только. Одна из «скал» у стены медленно поднимает клешню.","notes": "2 гигантских краба в лужах, Скрытность +4 против пассивной Внимательности героев.","map": "03-grot-bochek"},
{"session": 1,"scene": "Сцена 3. Грот Бочек","id": "s1-frame","title": "Пустая рама","when": "Герои входят в дальний грот (зона 6)","trigger": "находка","text": "Посреди грота стоит деревянная рама в два человеческих роста, почерневшая от воды и времени. На перекладине висят обрывки ржавой цепи. Под рамой на камне — глубокие свежие борозды. Они тянутся к чёрной воде у дальней стены, где волна дышит в узкий лаз, ведущий в открытое море.","notes": "Расследование СЛ 12: знак певчих (открытый рот и три волны). Записка «М.» лежит в сундуке Дожа (зона 3) — её можно выдать и как записку на столе.","map": "03-grot-bochek","variants": [{"if": "когда герои открывают сундук Дожа (зона 3) и читают записку","text": "— Записка, женский почерк: «Маяк. Новая луна. Колокол на место огня. Отец не должен знать. — М.»"}]},
{"session": 1,"scene": "Сцена 3. Грот Бочек","id": "s1-tamsi","title": "Тамси Крейн","when": "Герои выбираются из грота наружу","trigger": "встреча NPC","text": "Когда вы выбираетесь из грота, на камне у входа сидит девчонка лет семнадцати в слишком большой куртке и грызёт яблоко. Она даже не пытается делать вид, что пришла только что. «Ну наконец-то. Я тут с утра. Дядя Орвин велел следить за Дожем. Так это вы те, кто вытащил Тоби? Я знаю тропу к маяку. По берегу — полдня, по моей — час. Беру недорого: возьмёте меня с собой».","notes": "Новый уровень → 3. Тамси присоединяется: КД 14, ХП 21."},
{"session": 1,"scene": "Сцена 4. Маяк Седой Бран","id": "s1-lighthouse","title": "Зелёный свет на маяке","when": "Герои выходят с тропы Тамси к мысу, маяк виден впереди","trigger": "вход в локацию","text": "Тропа Тамси поднимается по скалам, и через час вы видите мыс. Маяк погас, но на его вершине горит другой свет — зелёный, как вода у самого дна. Сквозь ветер слышно пение: несколько голосов тянут одну ноту, без слов. И под это пение медленно, раз за разом, раскачивается что-то тяжёлое, отбрасывая на туман огромную тень.","notes": "Таймер ритуала — 10 раундов с момента, когда герои входят во двор (зона 1).","map": "04-mayak"},
{"session": 1,"scene": "Сцена 4. Маяк Седой Бран","id": "s1-bran","title": "Смотритель Бран","when": "Герои заглядывают в домик смотрителя (зона 2)","trigger": "встреча NPC","text": "Дверь домика приоткрыта. Внутри холодный очаг, перевёрнутый стол и старик, привязанный к стулу. Седая борода, разбитая губа. Увидев вас, он не зовёт на помощь, а шепчет: «Тише. Не дайте ей закончить песню».\n\n— Смотритель Бран: «Мейв, дочка моя… Мать её утонула в ту ночь, сорок лет назад. И вот эта, в воде, пообещала Мейв, что вернёт мать. Колокол нельзя разбить, я пробовал — в молодости монахи учили. Его можно заглушить. Тряпка в масле, обмотать язык, и поджечь. Масло — на среднем ярусе, вот ключ. И… прошу. Не убивайте её».","notes": "Бран даёт ключ от среднего яруса: масло, чтобы заглушить колокол.","map": "15-domik-smotritelya"},
{"session": 1,"scene": "Сцена 4. Маяк Седой Бран","id": "s1-cultists","title": "Певчие у подножия","when": "Герои входят в основание башни (зона 3)","trigger": "начало боя","text": "Внутри башни темно, только сверху, по спирали лестницы, сочится зелёный свет. У подножия стоят двое в мокрых серых балахонах. Их губы двигаются, они тоже поют, и пение не прерывается, даже когда они поднимают ятаганы.","notes": "2 культиста. Если оба живы на 5-м раунде — ритуал ускоряется на 1 раунд.","map": "04-mayak"},
{"session": 1,"scene": "Сцена 4. Маяк Седой Бран","id": "s1-maeve","title": "Колокол на месте огня","when": "Герои поднимаются на фонарную площадку (зоны 5–6)","trigger": "начало боя","text": "Наверху нет фонаря. На его месте, на новой цепи и лебёдке, висит бронзовый колокол, позеленевший от моря. Вокруг — круг из ракушек и мокрых свечей, которые горят зелёным. Молодая женщина в сером, с распущенными мокрыми волосами, раскачивает колокол за верёвку и поёт. За перилами галереи что-то мокрое и чешуйчатое переваливается через край.\n\n— Мейв: «Уходите. Вы не понимаете. Она вернёт всех. Маму. Всех, кого забрало море. Ещё немного, ещё совсем немного… Не подходите!»","notes": "Мейв и сахуагин с галереи. Остановить ритуал: убить или убедить Мейв (Убеждение СЛ 15), заглушить колокол (Ловкость СЛ 12 с тканью в масле и огнём) или сорвать его (Атлетика СЛ 15).","map": "04-mayak"},
{"session": 1,"scene": "Сцена 4. Маяк Седой Бран","id": "s1-ritual-end","title": "Чем кончился ритуал","when": "Сразу после боя на площадке — выберите вариант по тому, что случилось","trigger": "развязка","text": "Прочитайте один из вариантов ниже.","notes": "Колокол зазвонил — Шкала Мглы +1. Ритуал сорван — Шкала Мглы −1.","map": "04-mayak","variants": [{"if": "если колокол зазвонил","text": "Звук идёт не наружу, а внутрь — в кости, в зубы, в сердце. Туман вокруг маяка вздрагивает и поднимается стеной. Внизу, в городе, одно за другим открываются окна."},
{"if": "если ритуал сорван","text": "Колокол дёргается, гудит глухо, как больной зверь, и замолкает. Зелёные свечи гаснут разом. Впервые за месяц вы слышите обычный звук моря — просто волны."}]},
{"session": 1,"scene": "Финал сессии 1","id": "s1-veira","title": "Женщина на волнах","when": "Сразу после развязки на маяке — перед наградами","trigger": "катсцена","text": "Внизу, под обрывом, море вдруг становится гладким, как стекло. Из воды поднимается фигура — женщина в белом платье, сотканная из воды и пены. Она стоит на волнах, как на полу, и поднимает лицо к вам. У неё спокойная, почти ласковая улыбка.\n\n— Вейра Тиш: «Вы храбрые. Мне жаль, что вы опоздали. На сорок лет. Бронзовый — только первый голос. Серебряный ждёт меня в монастыре святой Ольвен, на Чаячьем Хребте. Приходите, если хотите услышать, как поёт море. Я буду рада вам. Все рано или поздно приходят домой».\n\nФигура рассыпается брызгами. Туман над бухтой на мгновение светлеет, и далеко в море, на востоке, проступает чёрный силуэт скалистого острова. Потом туман смыкается снова.","notes": "Можно вместо или после текста показать катсцену «Голос из моря». Не называйте имя Вейры — она его не говорит.","map": "04-mayak","cutscene": "c1"},
{"session": 1,"scene": "Финал сессии 1","id": "s1-end","title": "Серебряный…","when": "Самый конец сессии, после наград и 4-го уровня","trigger": "конец сессии","text": "Ночью в доме Марты тихо. Только Тобиас ворочается во сне и шепчет одно слово, снова и снова, всё тише и тише: «Серебряный… серебряный…» За окном туман прижимается к стеклу, как будто тоже слушает.","notes": "Перед этим: Бран отдаёт Плащ ската, Коб платит 50 зм, Аделина рассказывает о Монастыре Отлива, Тамси обещает уговорить дядю Орвина. Новый уровень → 4."},
{"session": 2,"scene": "Начало сессии","id": "s2-recap","title": "Что было раньше","when": "Самое начало сессии, до сборов","trigger": "начало сессии","text": "В прошлый раз над маяком Седой Бран смолкла песня, но море ответило вам. Женщина из воды и пены стояла на волнах и улыбалась: «Серебряный ждёт меня в монастыре святой Ольвен». Вы получили новые силы, а Тобиас Грей всю ночь шептал во сне одно слово. Сегодня утром туман лежит над бухтой гуще прежнего.","notes": "Перенесите Шкалу Мглы. Положите 6 жетонов отлива. Тамси: ХП 28.","map": "01-region"},
{"session": 2,"scene": "Сцена 1. Сборы и отплытие","id": "s2-heron","title": "«Цапля» и капитан Орвин","when": "Герои приходят на причал к «Цапле»","trigger": "встреча NPC","text": "Солтхейвен провожает вас тишиной. Окна домов у воды заколочены досками, на дверях — свежие деревянные рыбки с именами. У причала покачивается «Цапля»: узкий двухмачтовый парусник с облупленной голубой краской и цаплей, вырезанной на носу. На палубе стоит широкоплечий мужчина с седой бородой, заплетённой в косу, и смотрит на Тамси так, будто хочет одновременно обнять её и отшлёпать.\n\n— Капитан Орвин Хейл: «Значит, это вы. Те, что таскают мою племянницу по маякам и пещерам». (Долгая пауза.) «Она жива. Это главное. До Чаячьего Хребта — пятнадцать золотых. Хотя… раз она с вами — садитесь так. Но запомните: на моём корабле никто не свистит, никто не плюёт за борт и никто, слышите, никто не звонит ни в какие колокола».\n\n— Тамси: «Дядя, они спасли полгорода. Можно хоть раз без лекции?» (Шёпотом героям:) «Он добрый. Просто в последний раз, когда море так пело, он потерял весь экипаж».","map": "05-paluba-tsapli"},
{"session": 2,"scene": "Сцена 1. Сборы и отплытие","id": "s2-adelina","title": "Карта дамбы","when": "Перед отплытием, когда к причалу поднимается сестра Аделина","trigger": "встреча NPC","text": "— Сестра Аделина: «Монастырь святой Ольвен открыт только в отлив. Шесть часов. Потом море возвращается и забирает всё, что не успело уйти. Монахи жили по колоколу отлива. Вы будете жить по нему тоже. И возьмите ещё затычек. Бесплатно. Мать простит мне одну бескорыстную сделку».","notes": "Дайте 5–10 минут на покупки. Напомните про Плащ ската."},
{"session": 2,"scene": "Сцена 2. Зубы Вдовы","id": "s2-reefs","title": "Зубы Вдовы","when": "«Цапля» входит в рифы — после сборов, перед боем","trigger": "катсцена","text": "Два часа «Цапля» идёт под парусом вдоль берега. Потом Орвин поворачивает штурвал, и впереди из тумана встают Зубы Вдовы — чёрные рифы, острые, как обломки клинков. Ветер стихает. Паруса обвисают. Вода между скалами становится чёрной и неподвижной, как масло.\n\n— Капитан Орвин: «Тихо все. Море Матерь, проведи нас, проведи, мы не за твоим идём…» (Его губы продолжают шевелиться без звука.)","notes": "Катсцена «Отплытие «Цапли»» стоит здесь — покажите её до текста.","map": "05-paluba-tsapli","cutscene": "c2"},
{"session": 2,"scene": "Сцена 2. Зубы Вдовы","id": "s2-merrow","title": "Рука над бортом","when": "Сразу после молитвы Орвина — начало боя с мерроу","trigger": "начало боя","text": "Что-то царапает борт снизу. Медленно, от носа к корме, будто проверяет дерево на прочность. Скрежет обрывается. Тишина. А потом из воды поднимается рука — серо-зелёная, с перепонками, размером с весло, — и хватается за леер. Палуба кренится. Над бортом появляется голова: рыбьи глаза, пасть, полная треугольных зубов, и ржавый гарпун на верёвке.","notes": "2 мерроу лезут со скал (зона 6). Гарпун тянет цель на 20 фт, в том числе за борт. Мокрая палуба: Акробатика СЛ 10 при движении больше половины скорости.","map": "05-paluba-tsapli"},
{"session": 2,"scene": "Сцена 2. Зубы Вдовы","id": "s2-after-merrow","title": "Ветер возвращается","when": "Последний мерроу побеждён или сбежал","trigger": "после боя","text": "Последний мерроу с плеском уходит под воду, оставив на досках длинный кровавый след. Ветер возвращается так же внезапно, как пропал. Паруса хлопают, и «Цапля» медленно выходит из рифов. На палубе, у самого борта, лежит что-то блестящее.","notes": "У вожака — серебряный колокольчик певчих (40 зм). Если взяли пленного — читайте реплику ниже.","map": "05-paluba-tsapli","variants": [{"if": "если мерроу взяли живым","text": "— Пленный мерроу: «Певчая… обещать нам. Город. Весь город. Тёплый, большой. Много мяса. Без вас. Без людей». (Скалится.) «Она звонить скоро. Вы все пойти вниз»."}]},
{"session": 2,"scene": "Сцена 2. Зубы Вдовы","id": "s2-ridge","title": "Чаячий Хребет","when": "К вечеру, когда «Цапля» подходит к монастырю","trigger": "катсцена","text": "К вечеру туман расступается, и впереди встаёт Чаячий Хребет: голая скала, облепленная криками птиц. На её вершине — серые стены монастыря, полуразрушенная колокольня без колокола. К монастырю тянется дамба из скользких чёрных камней. Вода вокруг неё отступает прямо у вас на глазах, обнажая водоросли и ракушки. Начался отлив.","notes": "Катсцена «Отлив». С этого момента идёт отсчёт отлива: 6 жетонов.","map": "06-monastyr-otliva","cutscene": "c3"},
{"session": 2,"scene": "Сцена 3. Монастырь Отлива","id": "s2-causeway","title": "Дамба","when": "Герои ступают на дамбу (зона 1)","trigger": "вход в локацию","text": "Камни дамбы покрыты зелёными водорослями, скользкими, как мыло. Под ногами хрустят ракушки. По обе стороны — лужи, в которых бьются оставленные морем рыбы. Чайки кружат над вами, но ни одна не садится на монастырь. Ни одна.","notes": "Кто бежит — Акробатика СЛ 10, иначе падает и 1d4 урона.","map": "06-monastyr-otliva"},
{"session": 2,"scene": "Сцена 3. Монастырь Отлива","id": "s2-gate","title": "Ворота с колокольчиками","when": "Герои подходят к арке ворот (зона 2)","trigger": "вход в локацию","text": "Арка ворот затянута сетью тонких нитей, и на каждой висит крошечный медный колокольчик. Их десятки, может быть, сотни. Ни один не звенит, хотя ветер дует прямо в арку. Нити неподвижны, будто воздух здесь застыл.","notes": "Внимательность СЛ 14 — нити натянуты. Провал обхода — звон, зомби из трапезной выходят во двор.","map": "06-monastyr-otliva"},
{"session": 2,"scene": "Сцена 3. Монастырь Отлива","id": "s2-well","title": "Двор и колодец","when": "Герои входят во двор (зона 3)","trigger": "находка","text": "Двор зарос солёной травой. Посередине — колодец с каменным бортиком и обрывком цепи. Из колодца пахнет пресной водой, а не морем. И ещё — чем-то сладковатым, старым. На дне, на высоте вытянутой руки над водой, застрял человек в серой рясе, сжимающий в руке свёрток из промасленной кожи.","notes": "Достать тело — Атлетика СЛ 10 с верёвкой. В свёртке — записка монаха (ниже, читайте, когда развернут).","map": "06-monastyr-otliva","variants": [{"if": "когда герои разворачивают свёрток","text": "— Записка монаха, дрожащий почерк: «Брат Эммерих, если ты жив: камертоны в часовне открывают склеп. Песнь святой Ольвен — в скриптории, в столе аббата. Не позволяй им звонить. Не позволяй ей петь. Я спрячусь в колодце. Вода поёт громче, но здесь её почти не слышно»."}]},
{"session": 2,"scene": "Сцена 3. Монастырь Отлива","id": "s2-refectory","title": "Монахи в трапезной","when": "Герои открывают двери трапезной (зона 4). Если звенели колокольчики — читайте во дворе","trigger": "начало боя","text": "Длинный зал с каменными столами. На столах — миски, в мисках — засохшие водоросли. За столами сидят монахи в серых рясах, мокрых до нитки, и смотрят в пустые миски. Их кожа серо-синяя, раздутая от воды. С ряс капает. Когда вы входите, четыре головы одновременно поднимаются и поворачиваются к вам. Глаз у них нет — только ракушки на месте глаз.","notes": "4 зомби. Бой дольше 5 раундов — снимите жетон отлива. За трапезной — оружие +1.","map": "06-monastyr-otliva"},
{"session": 2,"scene": "Сцена 3. Монастырь Отлива","id": "s2-scriptorium","title": "Скрипторий и дневник аббата","when": "Герои входят в скрипторий (зона 5); дневник — когда возьмут его в руки","trigger": "находка","text": "Пыль, свечные огарки и запах старой бумаги. Пол завален разбросанными книгами — кто-то искал здесь что-то в спешке. Стол у окна чистый, на нём лежит раскрытый дневник, придавленный медной чернильницей, будто его оставили специально, чтобы кто-то прочёл.\n\n— Дневник аббата Тальмира, последняя страница: «Вейра снова приходила ко мне во сне. Сорок лет назад она была лучшей послушницей, что я видел. Голос, от которого море затихало. Это я отправил её в Ис-Мерин звонить в Великий колокол в ночь шторма. Она ударила не в такт. Город ушёл под воду, она — вместе с ним. Теперь она хочет ударить ещё раз — правильно, как ей кажется. Я спрятал Жемчужину Дыхания у Серебряного колокола. Только с ней можно спуститься в Ис-Мерин и заглушить Великий. Песнь Ольвен — на обороте. Волна поднимается и отступает. Да простит меня Мать».","notes": "На обороте — ноты «Песни Ольвен» (выдайте записку). Секретная дверь в часовню — Расследование СЛ 13.","map": "06-monastyr-otliva"},
{"session": 2,"scene": "Сцена 3. Монастырь Отлива","id": "s2-chapel","title": "Часовня святой Ольвен","when": "Герои входят в круглую часовню (зона 6)","trigger": "вход в локацию","text": "Круглая часовня под куполом. По стене расставлены семь медных труб разной длины — от совсем короткой, с локоть, до высокой, в два человеческих роста. Каждая висит на цепи над каменной чашей. В центре — статуя женщины с закрытыми глазами и открытым ртом: святая Ольвен поёт. У её ног — медный молоточек на цепочке.","notes": "Порядок труб: 1-3-5-7-6-4-2. Без нот — Проницательность или Религия СЛ 15. Ошибка — 2d6 звуком всем (Тел СЛ 12 — половина).","map": "06-monastyr-otliva"},
{"session": 2,"scene": "Сцена 3. Монастырь Отлива","id": "s2-riddle","title": "Ответ из глубины","when": "Загадка камертонов решена","trigger": "находка","text": "Последняя нота висит в воздухе дольше, чем должна. Она не затихает, а уходит вниз, под пол, и где-то глубоко под вами ей отвечает другой звон — чистый, серебряный, тоскливый. Каменная плита у ног святой Ольвен с хрустом проседает, открывая ступени, уходящие в темноту.","map": "06-monastyr-otliva"},
{"session": 2,"scene": "Сцена 3. Монастырь Отлива","id": "s2-lira","title": "Лира Вейн","when": "Герои поднимаются к руинам звонницы (зона 8) — лучше после решения загадки","trigger": "встреча NPC","text": "От колокольни осталась половина: стены без крыши, лестница, обрывающаяся в небо. На верхней площадке, свесив ноги, сидит женщина в кожаной куртке с десятком карманов. Рыжие волосы стянуты платком, на поясе — два коротких клинка и связка отмычек. Она жуёт сушёную рыбу и смотрит на вас без малейшего удивления.\n\n— Лира Вейн: «О, конкуренты. Или спасатели мира? По лицам вижу — спасатели. Я Лира. Охотница за реликвиями, по-вашему воровка. Я тут два дня и до сих пор не разгадала эти проклятые трубы. А вы, вижу, разгадали — пол в часовне так грохнул, что чайки улетели». (Спрыгивает вниз.) «Предложение: внизу Серебряный колокол. В столице за него дадут пять тысяч. Я помогаю вам пройти, вы мне — колокол. Или делим. Или деремся. Я, честно говоря, предпочла бы первое».","notes": "Честный договор — Убеждение СЛ 12; угрозы — Запугивание СЛ 15 (идёт следом тайком). Правда про Вейру (Проницательность СЛ 13) — Лира задумывается о казне Ис-Мерина.","map": "06-monastyr-otliva"},
{"session": 2,"scene": "Сцена 4. Склеп Серебряного колокола","id": "s2-stairs","title": "Бесконечная лестница","when": "Герои спускаются по лестнице из часовни (зона 7)","trigger": "вход в локацию","text": "Лестница уходит вниз так долго, что вы перестаёте считать ступени. Стены становятся мокрыми, потом покрываются солью, похожей на иней. Снизу тянет холодом и чем-то ещё — едва слышным звоном, как будто кто-то далеко-далеко провёл пальцем по краю бокала. Звон не прекращается ни на секунду.","notes": "Новый уровень → 5 при спуске. Тамси: ХП 35.","map": "07-sklep-kolokola"},
{"session": 2,"scene": "Сцена 4. Склеп Серебряного колокола","id": "s2-ghouls","title": "Галерея саркофагов","when": "Герои дошли до середины галереи (зона 2)","trigger": "начало боя","text": "Длинная галерея. По обе стороны — каменные саркофаги, на крышках вырезаны монахи со сложенными руками. На середине галереи вы слышите скрежет. Крышка ближайшего саркофага медленно сдвигается. Из темноты появляются пальцы — длинные, серые, с чёрными когтями. За ними — лицо, обтянутое кожей, с голодной улыбкой до ушей.","notes": "2 гуля. Паралич когтей: Тел СЛ 10. Эльфы невосприимчивы.","map": "07-sklep-kolokola"},
{"session": 2,"scene": "Сцена 4. Склеп Серебряного колокола","id": "s2-echo","title": "Зал эха","when": "Герои входят в круглый зал (зона 3)","trigger": "вход в локацию","text": "Зал круглый, со сводом, похожим на внутренность раковины. Когда вы входите, ваши шаги возвращаются к вам втрое громче. Даже дыхание здесь звучит, как шум прибоя.","notes": "Вербальные заклинания здесь: Тел СЛ 12 или глухота на 1 минуту. Оглохшие невосприимчивы к Звону Стража — намекните через Тамси: «Слышите? Тут даже думать громко».","map": "07-sklep-kolokola"},
{"session": 2,"scene": "Сцена 4. Склеп Серебряного колокола","id": "s2-crypt","title": "Затопленная крипта","when": "Герои входят в зону 4","trigger": "находка","text": "Пол уходит под воду. Вода по пояс, ледяная и прозрачная, как стекло. На дне белеют кости и что-то мерцает — три бледных огонька, словно звёзды, упавшие в колодец.","notes": "3 жемчужины по 100 зм и ржавый ключ от ниши алтаря. Атлетика СЛ 10 или Плащ ската.","map": "07-sklep-kolokola"},
{"session": 2,"scene": "Сцена 4. Склеп Серебряного колокола","id": "s2-guardian","title": "Колокольный Страж","when": "Герои входят в Колокольный зал (зона 5)","trigger": "начало боя","text": "Зал огромный. В центре, на чёрной цепи, висит колокол — не больше бочки, но серебро сияет так, будто его отлили вчера. Звон, который вы слышали всю дорогу, идёт от него, хотя колокол неподвижен. Перед колоколом стоит фигура в два человеческих роста. Её доспех собран из старых колоколов: плечи — два колокола, грудь — огромный треснутый колокол, голова — маленький колокольчик без языка. Когда вы делаете шаг, фигура поворачивается. Внутри неё что-то гудит.","notes": "Страж охраняет колокол от всех. В раунде 3 из шахты поднимается проекция Вейры — читайте следующий текст.","map": "07-sklep-kolokola"},
{"session": 2,"scene": "Сцена 4. Склеп Серебряного колокола","id": "s2-projection","title": "Песня проекции","when": "Раунд 3 боя со Стражем — из шахты поднимается вода","trigger": "встреча NPC","text": "Из шахты за колоколом поднимается вода. Она не льётся — она встаёт столбом и складывается в фигуру женщины в белом платье. Та же улыбка, что над маяком.\n\n— Вейра Тиш: «Вы всё-таки пришли. Хорошо. Мне нравится, когда меня слушают. Брат Тальмир тоже слушал. Потом перестал. Послушайте. Это недолго…»","notes": "Прервать песню: 10+ урона одним ударом (КД 12) или Выступление СЛ 15. Не прервали до конца раунда 4 — колокол звенит, Шкала Мглы +1.","map": "07-sklep-kolokola"},
{"session": 2,"scene": "Сцена 4. Склеп Серебряного колокола","id": "s2-guardian-falls","title": "Страж рассыпается","when": "Колокольный Страж падает","trigger": "после боя","text": "Колокола, из которых он сложен, звенят все разом — нестройно, жалобно — и рассыпаются по полу. Последним падает маленький колокольчик-голова. Он катится к вашим ногам и затихает. Серебряный колокол над вами продолжает тихо петь.","map": "07-sklep-kolokola"},
{"session": 2,"scene": "Сцена 4. Склеп Серебряного колокола","id": "s2-altar","title": "Жемчужина Дыхания","when": "Герои открывают нишу за колоколом (зона 6)","trigger": "находка","text": "За колоколом — ниша, закрытая ржавой решёткой. Внутри на каменном алтаре стоит раковина размером с ладонь. В раковине, на подушке из водорослей, лежит жемчужина — крупная, с голубиное яйцо. Она светится изнутри мягким голубым светом, и свет пульсирует, как будто дышит.","notes": "Решётка: ключ из крипты, Атлетика СЛ 16 или инструменты СЛ 15. Жемчужина — все в 30 фт дышат под водой. Камертон Ольвен, 250 зм.","map": "07-sklep-kolokola"},
{"session": 2,"scene": "Финал сессии 2","id": "s2-silver","title": "Серебряный колокол звонит сам","when": "Жемчужина взята — море возвращается в монастырь","trigger": "катсцена","text": "Пол дрожит. Сверху, по лестнице, доносится рёв — море вернулось и заливает монастырь. В шахте за алтарём вода поднимается, бурлит, и вдруг — Серебряный колокол звонит. Сам. Никто его не трогал. Звук чистый и долгий, и вода в шахте расступается, как занавес.\n\nДалеко внизу, на дне бухты, вспыхивает свет. Бледный купол, похожий на мыльный пузырь размером с небо, дрожит над крышами и башнями утонувшего города. Улицы, площади, мосты — всё целое, всё ждёт. В центре города — самая высокая башня, и на её вершине что-то огромное отливает тёмной бронзой. Великий колокол. Путь открыт. Для всех.\n\n— Тамси: «Это… это Ис-Мерин? Дядя рассказывал, но я думала — сказки». (Пауза.) «Я иду с вами. И не спорьте».","notes": "Катсцена «Купол на дне» — сразу после первого абзаца.","map": "01-region","cutscene": "c4"},
{"session": 2,"scene": "Финал сессии 2","id": "s2-lira-choice","title": "Решение Лиры","when": "Если Лира с героями — сразу после реплики Тамси","trigger": "развязка","text": "Лира смотрит то на колокол, то на светящийся город далеко внизу. Решение уже написано у неё на лице.","variants": [{"if": "если с ней поступили честно","text": "— Лира Вейн: «Колокол, говорите, пять тысяч… А там внизу — казна целого города. Знаете что? Пусть колокол висит. Я с вами. Только чур, первый сундук — мой»."},
{"if": "если её обманули или запугали","text": "— Лира Вейн: «Без обид, ребята. Бизнес». (Срывает колокол с цепи (если ещё висит) и прыгает в шахту. Её не видно до Сессии 3.)"}]},
{"session": 2,"scene": "Финал сессии 2","id": "s2-end","title": "Ваши имена в песне","when": "Самый конец сессии, после наград и 6-го уровня","trigger": "конец сессии","text": "Звон затихает. В шахте стоит неподвижная вода, и сквозь неё виден бледный купол на дне. И тогда снизу, очень издалека, поднимается голос. Женщина поёт — тихо, ласково, как колыбельную. Вы не сразу понимаете, почему по спине бежит холод. В песне звучат ваши имена.","notes": "Длинный отдых можно сделать в склепе. Если жетоны отлива остались — Орвин ждёт у скал. Новый уровень → 6, Тамси: ХП 42."},
{"session": 3,"scene": "Начало: над Разломом","id": "s3-anchor","title": "«Цапля» над Разломом","when": "Самое начало сессии, на борту «Цапли» перед спуском","trigger": "начало сессии","text": "«Цапля» стоит на якоре посреди бухты, там, где вода всегда чуть темнее, чем вокруг. Орвин не спал всю ночь: сидел у штурвала с трубкой, которую так и не раскурил. Рассвет не наступил — небо просто стало серым. Под килем, глубоко внизу, светится бледное пятно, будто кто-то зажёг на дне луну. Это купол над Ис-Мерином. Открытый Серебряным колоколом путь ждёт вас. И не только вас.\n\n— Капитан Орвин Хейл: «Я буду ждать здесь до следующего рассвета. Если к тому времени вы не всплывёте… Нет. Всплывёте». (Смотрит на Тамси.) «А ты. Держись за ними, слышишь? Не лезь первой. Не воруй ничего у мёртвых. И вернись. Мать мне голову оторвёт».\n\n— Тамси Крейн: «Дядя, ты повторяешь это уже третий раз. Я поняла с первого. Ну… со второго». (Тише, героям:) «Если там внизу правда целый город — я хочу увидеть. Хоть раз в жизни. Даже если страшно».","notes": "Если Шкала Мглы 3+ — спасбросок Мудрости СЛ 11 после ночи на борту. Если с героями Лира — она спрашивает про делёж казны.","map": "01-region"},
{"session": 3,"scene": "Сцена 1. Спуск","id": "s3-descent","title": "Спуск под купол","when": "Герои шагают в шахту с Жемчужиной Дыхания","trigger": "катсцена","text": "Жемчужина тёплая, как живое сердце. Когда вы шагаете в шахту, вода расступается, и вокруг каждого из вас остаётся тонкая плёнка воздуха. Она дрожит при каждом вдохе. Вниз, вниз, сквозь холод и тишину. Мимо проплывают рыбы, которые никогда не видели солнца: прозрачные, с огоньками вместо глаз. Свет над головой гаснет. Потом гаснет совсем. А потом под ногами появляется мостовая, а над головой — купол, дрожащий, как мыльный пузырь размером с небо.\n\nИс-Мерин лежит перед вами целиком. Улицы, площади, лестницы, крыши, покрытые ракушками, как черепицей. Окна светятся зеленоватым светом. На набережной висят сети, которые никто не снимал сорок лет. И над всем этим, в центре города, поднимается башня. На её вершине, под аркой, висит колокол такой величины, что в нём можно было бы поставить дом. Он молчит. Пока.\n\n— Тамси Крейн: «Тут… кто-то живёт? Смотрите, на подоконнике цветок в горшке. Коралловый. Кто-то его поливает. Морем, наверное. Ладно, я ничего не говорила, мне не страшно».","notes": "Катсцена «Спуск в Ис-Мерин» стоит здесь. Шкала 4+: купол трещит, площади — трудная местность.","map": "08-is-merin","cutscene": "c5"},
{"session": 3,"scene": "Сцена 2. Улицы утонувшего города","id": "s3-square","title": "Площадь Ракушек","when": "Герои выходят на площадь (место 2)","trigger": "вход в локацию","text": "Площадь выложена ракушками: белыми, розовыми, перламутровыми, тысячи и тысячи. Они хрустят под ногами. В центре стоит фонтан, но вместо воды из него поднимаются пузыри воздуха. У фонтана ходят кругами пятеро. Чешуя, плавники, длинные копья. Впереди — высокая фигура в ожерелье из зубов, она нюхает воздух, как собака. И поворачивает голову к вам.","notes": "Обойти: групповая Скрытность СЛ 14. Провал — бой с жрицей и 4 сахуагинами.","map": "08-is-merin"},
{"session": 3,"scene": "Сцена 2. Улицы утонувшего города","id": "s3-priestess","title": "Жрица сахуагинов","when": "Сахуагины заметили героев — начало боя на площади","trigger": "начало боя","text": "— Жрица сахуагинов: (На ломаном Общем, шипя:) «Сухие. Тёплые. Певчая сказала: сухие придут. Певчая сказала: сухих — нам. Весь берег — нам».","notes": "Жрица первым ходом — удержание личности на сильнейшего бойца. Если жрица падает, двое бегут предупредить Вейру.","map": "08-is-merin"},
{"session": 3,"scene": "Сцена 2. Улицы утонувшего города","id": "s3-market","title": "Коралловый рынок","when": "Герои входят на улицу-рынок (место 3)","trigger": "встреча NPC","text": "Узкая улица превращена в рынок. Прилавки из коралла, корзины, весы. За прилавками стоят торговцы — полупрозрачные, бледно-голубые, сквозь них видна стена. Они улыбаются и зовут вас, но голоса доходят с опозданием, как эхо. Перед одним из прилавков на камне лежит табличка: «Товар — за живое».\n\n— Призрачный торговец: «Подходите, подходите, добрые господа! Сорок лет никто не покупал. Сорок лет! Я не прошу золота, золото здесь никому не нужно. Дайте мне что-нибудь тёплое. Прядь волос. Песню. Ваше первое воспоминание о матери. И забирайте, что нравится».","notes": "Каждая покупка: Мудрость СЛ 13, провал — персонаж забывает своё имя до конца сессии. Не говорите об этом заранее.","map": "08-is-merin"},
{"session": 3,"scene": "Сцена 2. Улицы утонувшего города","id": "s3-edren","title": "Эдрен, призрак глашатая","when": "Герои входят в Дом Глашатая (место 4)","trigger": "встреча NPC","text": "Высокий дом с резными дверями, над входом — бронзовый рог, позеленевший от моря. Внутри, у потухшего камина, сидит старик в парадном камзоле. Он прозрачен, как туман, и на его коленях лежит свиток. Он встаёт, когда вы входите, и кланяется — медленно, со скрипом, хотя скрипеть ему нечему.\n\n— Эдрен, призрак глашатая: «Да пребудет с вами милость Матери Вод, путники сухого мира. Я, Эдрен, глашатай короля Ольда Третьего, сорок лет жду, когда кто-нибудь придёт выслушать последнюю весть. Слушайте же. Певчую Вейру нельзя сразить, покуда звучит хоть один колокол: жизнь её сплетена с их голосом. Великий колокол держится на трёх цепях. Разбейте цепи — и колокол падёт, и умолкнет, и певчая станет смертна, как вы и я. Как я когда-то».","notes": "Если пропустили — Эдрен встречает их у моста. Про сокровища — ключ от казны.","map": "08-is-merin"},
{"session": 3,"scene": "Сцена 2. Улицы утонувшего города","id": "s3-archive","title": "Последняя запись летописи","when": "Герои входят в архив (место 5); летопись — после проверки История/Расследование СЛ 13","trigger": "находка","text": "Полки до потолка, свитки в восковых футлярах. Здесь сухо — единственное сухое место во всём городе. На столе у окна лежит раскрытая летопись, и на последней странице чернила расплылись, будто писавший плакал.\n\n— Последняя запись летописи: «Год чумы, месяц бурь. Мор уносит по двадцать душ в день. Старшая певчая Вейра Тиш ушла в Разлом с тремя колоколами, чтобы просить Безмолвный Прилив о милости. Прилив ответил: город будет жить вечно. Вода поднялась этой ночью. Мы живём. Да простит нас Мать Вод — мы живём».","notes": "Свиток с печатью храма — ключ к мирной концовке. Выдайте его как записку.","map": "08-is-merin"},
{"session": 3,"scene": "Сцена 2. Улицы утонувшего города","id": "s3-garden","title": "Сад анемонов","when": "Герои выбирают короткую дорогу через сад (место 6)","trigger": "вход в локацию","text": "Короткая дорога к башне ведёт через сад. Вместо деревьев здесь колышутся анемоны в человеческий рост — алые, лиловые, с мягкими щупальцами. Они тянутся к вам, как цветы к солнцу. Красиво. Очень красиво.","notes": "Каждые 10 фт — Тел СЛ 13 или 2d6 ядом и отравление. Природа/Выживание СЛ 14 — проход вдоль стены.","map": "08-is-merin"},
{"session": 3,"scene": "Сцена 2. Улицы утонувшего города","id": "s3-bridge","title": "Глаз в Разломе","when": "Герои доходят до середины моста (место 7)","trigger": "начало боя","text": "Узкий каменный мост перекинут через трещину в дне моря. Перил нет. Внизу — тьма, такая глубокая, что в неё больно смотреть. Из тьмы поднимается тёплое течение, пахнущее солью и чем-то древним. Посреди моста вы чувствуете взгляд. Далеко внизу, во мраке, медленно открывается глаз. Он больше, чем «Цапля». Он просто смотрит. Потом закрывается.","notes": "Мудрость СЛ 13 или испуг на 1 минуту. Сразу после — 2 мерроу с двух сторон и акула под мостом.","map": "08-is-merin"},
{"session": 3,"scene": "Сцена 2. Улицы утонувшего города","id": "s3-after-bridge","title": "Тамси после моста","when": "Бой на мосту окончен, перед паузой на 7-й уровень","trigger": "после боя","text": "— Тамси Крейн: «Вы видели? Этот глаз… Он на меня посмотрел. Ладно. Ладно! Всё нормально. Пойдём уже к этой башне, пока я не передумала и не уплыла обратно к дяде».","notes": "Обязательная пауза: новый уровень → 7, Тамси: ХП 49."},
{"session": 3,"scene": "Сцена 3. Колокольная башня","id": "s3-tower","title": "Двери башни","when": "Герои входят в нижний зал башни (место 2)","trigger": "вход в локацию","text": "Двери башни открыты настежь. Внутри — зал с колоннами, и пол уже залит водой по щиколотку. Вода прибывает. Наверх ведёт широкая винтовая лестница, и сверху льётся пение: два голоса, высоких и чистых, без слов. Пение такое красивое, что хочется сесть на ступени и слушать, пока вода не поднимется до горла.","notes": "Вода поднимается на 1 фут каждый раунд. Обвалившаяся лестница: разрыв 10 фт, Атлетика СЛ 10.","map": "09-kolokolnaya-bashnya"},
{"session": 3,"scene": "Сцена 3. Колокольная башня","id": "s3-choir","title": "Балкон хористов","when": "Герои поднимаются к балкону (место 4)","trigger": "начало боя","text": "Прочитайте вариант по Шкале Мглы.","notes": "Пока поют певчие (или жив элементаль), Вейра получает 10 временных ХП в начале хода. Тишина от Камертона Ольвен прерывает пение.","map": "09-kolokolnaya-bashnya","variants": [{"if": "если Шкала Мглы 4 или меньше — певчие","text": "На балконе над лестницей стоят двое в серых балахонах, с мокрыми волосами. Они держатся за руки и поют, глядя вверх, на Великий колокол. Они вас видят. Но не перестают петь."},
{"if": "если Шкала Мглы 5+ — водяной элементаль","text": "Певчих на балконе нет. Вместо них там стоит столб воды в два человеческих роста. Он вращается, гудит, и в его глубине вы видите очертания лица — оно открывает рот вместе с пением, которое доносится сверху."}]},
{"session": 3,"scene": "Сцена 3. Колокольная башня","id": "s3-summit","title": "Певчая на троне","when": "Герои выходят на вершину (места 5–7) — перед финальным боем","trigger": "катсцена","text": "Лестница выводит на открытую площадку под каменной аркой. Великий колокол выше любого дома в Солтхейвене. Он висит на трёх цепях, толстых, как якорные, и вокруг него стоит тишина, такая плотная, что слышно собственное сердце. На краю площадки, на троне из чёрного коралла, сидит женщина в мокром белом платье. В руке у неё трезубец из жемчуга. Она поднимает голову и улыбается вам, как старым знакомым.\n\n— Вейра Тиш: «Вот и вы. Я ждала. Правда ждала — вы первые живые гости за сорок лет. Садитесь, если хотите. Нет? Жаль. Я знаю, зачем вы пришли. Вы думаете, я чудовище. А я просто хочу, чтобы мои дети снова бегали по этой площади. Чтобы торговцы на рынке продавали рыбу, а не воспоминания. Чтобы над Ис-Мерином снова было солнце. Разве это так страшно? Один удар. Один. И все вернутся домой».","notes": "Катсцена «Певчая на троне» стоит здесь. Дайте героям ответить. Если промолчали или отказались — Вейра встаёт: «Значит, вы останетесь здесь. В Ис-Мерине всем хватит места». Начинается бой.","map": "09-kolokolnaya-bashnya","cutscene": "c6"},
{"session": 3,"scene": "Сцена 3. Колокольная башня","id": "s3-scroll","title": "Свиток показан","when": "Во время разговора или боя герои показывают Вейре свиток из архива","trigger": "развязка","text": "— Вейра Тиш: (Долго смотрит на печать.) «Я помню этот свиток. Я сама его запечатала. Он сказал: город будет жить вечно. И город… живёт. Вот так. Под водой. Сорок лет.» (Голос впервые дрожит.) «Нет. Нет, вы лжёте. Он обещал. Он обещал мне».","notes": "Помеха на её атаки 1 раунд. Мирная концовка: Убеждение СЛ 18 (преимущество при Шкале ≤ 2).","map": "09-kolokolnaya-bashnya"},
{"session": 3,"scene": "Сцена 3. Колокольная башня","id": "s3-chain1","title": "Первая цепь","when": "Падает первая из трёх цепей Великого колокола","trigger": "находка","text": "Цепь лопается с таким звуком, будто рвётся струна размером с мачту. Колокол кренится, и от него идёт низкий стон — не звон, а стон, как у раненого кита. Вейра оборачивается к нему, и на её лице впервые нет улыбки.","map": "09-kolokolnaya-bashnya"},
{"session": 3,"scene": "Сцена 3. Колокольная башня","id": "s3-chain3","title": "Колокол срывается","when": "Падает последняя цепь — Вейра становится смертной","trigger": "развязка","text": "Великий колокол срывается. Он падает сквозь площадку, сквозь пол, сквозь лестницу, ломая камень, как лёд, и уходит вниз, в темноту под башней. Удара о дно вы не слышите. Только тишину. Настоящую тишину — впервые за сорок лет. Вейра стоит на краю пролома, и с её волос капает обычная, просто солёная вода.\n\n— Вейра Тиш: «Что вы наделали… Вы хоть понимаете, что вы наделали? Они больше никогда… никогда…» (Поднимает трезубец.) «Тогда я останусь с ними. И вы тоже».","notes": "Вейра теряет Песнь Глубин и Связь колоколов. Бой продолжается.","map": "09-kolokolnaya-bashnya"},
{"session": 3,"scene": "Концовки","id": "s3-end-killed","title": "Концовка: колокол заглушён, Вейра убита","when": "Вейра падает после того, как рухнул колокол","trigger": "развязка","text": "Вейра падает на колени. Она не кричит. Она смотрит вниз, на город, и шепчет одно слово — имя, которое вы не знаете. Потом её тело становится водой и стекает по ступеням, как будто его никогда не было. Купол над городом вздрагивает. По нему бегут трещины, светлые, как молнии. Жемчужина в ваших руках вспыхивает, и вас поднимает вверх — быстро, быстрее, чем можно вдохнуть. Внизу, под вами, Ис-Мерин гаснет окно за окном. Медленно. Как город, который наконец ложится спать.\n\nВы выныриваете у борта «Цапли» в серой утренней воде. Орвин молча втаскивает вас на палубу, одного за другим, и только когда последний оказывается на досках, начинает ругаться — длинно, со вкусом и со слезами. А над бухтой расходится туман. Впервые за месяц вы видите солнце. И на берегу, у Солтхейвена, из воды выходят люди. Мокрые, растерянные, в ночных рубахах. Живые.","notes": "Катсцена «Рассвет» — после первого абзаца.","cutscene": "c7"},
{"session": 3,"scene": "Концовки","id": "s3-end-peace","title": "Концовка: Вейра убеждена","when": "Убеждение СЛ 18 после свитка удалось — бой прекращается","trigger": "развязка","text": "— Вейра Тиш: «Сорок лет. Сорок лет я пела им колыбельную и думала, что это песня пробуждения.» (Опускает трезубец.) «Хорошо. Тогда я спою ему. Ему, там внизу. Пусть спит. Пусть спит вечно, а с ним и мой город. Это будет моя последняя служба. Вы были добры ко мне. Это больше, чем я заслужила».\n\nВейра сама поднимается к колоколу и одним движением трезубца разрубает цепи. Колокол падает в Разлом, и она шагает следом, не оглядываясь. Из глубины поднимается песня — тихая, без слов, бесконечно печальная. Вы слышите её всю дорогу наверх. И каждый из вас запомнит её навсегда.","notes": "Награда: благословение Песни (+1 к спасброскам Мудрости навсегда) каждому герою и Тамси. Катсцену «Рассвет» можно показать после текста.","cutscene": "c7"},
{"session": 3,"scene": "Концовки","id": "s3-end-bell","title": "Концовка: колокол прозвенел","when": "Шкала Мглы дошла до 6 или Вейра успела ударить в Великий колокол","trigger": "развязка","text": "Звон проходит сквозь вас, сквозь башню, сквозь море. Купол лопается — но вода не падает. Она уходит вверх. Весь Ис-Мерин поднимается со дна вместе с вами: улицы, площади, крыши в ракушках. Город выходит на поверхность посреди бухты, мокрый и светящийся, и в окнах загораются огни. А далеко внизу, в Разломе, что-то огромное просыпается.","notes": "У героев есть время до заката, чтобы вывести жителей Солтхейвена. Это конец кампании и начало следующей.","cutscene": "c8"},
{"session": 3,"scene": "Эпилог","id": "s3-epilogue","title": "Праздник в Солтхейвене","when": "После любой концовки, кроме «колокол прозвенел»","trigger": "конец сессии","text": "Через три дня Солтхейвен устраивает праздник. Первый за много лет. На причале жарят рыбу, Ингрид выкатывает бочку из погреба и не берёт ни медяка. Сестра Аделина снимает с верёвки у алтаря деревянных рыбок — одну за другой, тех, кто вернулся. Их девять. Две рыбки она оставляет висеть.\n\n— Староста Коб: «Тише, тише, ради всех… а, к чёрту. Пусть шумят!» (Вручает героям свиток с печатью.) «Почётные граждане Солтхейвена. Бесплатный ночлег в «Баклане» до конца жизни. Ингрид, не спорь, город платит. Наверное».\n\n— Смотритель Бран: (Рядом с ним стоит Мейв, бледная, с коротко остриженными волосами.) «Маяк снова горит. Обычным огнём. Мы с дочкой теперь сменяемся ночами. Спасибо вам. За неё — особенно».\n\n— Тамси Крейн: «Дядя сказал, что я теперь первый помощник. Первый! Ну, кроме него больше никого нет, но всё равно. Если вам когда-нибудь опять понадобится в море — вы знаете, где искать «Цаплю». И… это. Спасибо. Что взяли меня с собой. Вы лучше любой сказки».","notes": "Новый уровень → 8. Потом спросите каждого игрока, что его герой делает дальше. Крючок: если Прилив видел героев на мосту, через месяц Тобиас снова говорит во сне — чужим голосом.","map": "02-solthaven"}];
